sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float count;
uniform float width;
uniform float angle;
uniform float phase;
layout(color) uniform half4 color;
uniform float punch;
uniform float smoothing;
uniform float screenSpace;
uniform float style;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float2 origin = screenSpace > 0.5 ? screen.xy + screen.zw * 0.5 : size * 0.5;
    float a = radians(angle);
    float d = dot(coord - origin, float2(-sin(a), cos(a)));
    float s;
    if (style > 0.5) {
        float period = (screenSpace > 0.5 ? screen.w : length(size)) / max(count, 0.5);
        float f = fract(d / period - phase);
        float w = clamp(width, 0.0, 1.0);
        float soft = max(smoothing, 0.0);
        s = soft > 0.0 ? smoothstep(1.0 - w, 1.0 - w + soft, f) * (1.0 - smoothstep(1.0 - soft, 1.0, f)) : step(1.0 - w, f);
        s *= step(0.0001, w);
    } else {
        float period = (screenSpace > 0.5 ? screen.w : size.y) / (2.475 * max(count, 0.5));
        float e = abs(fract(d / period + phase) - 0.5);
        float edge = max(smoothing * 0.5, 0.5 * 1.0 / period);
        s = 1.0 - smoothstep(width * 0.5 - edge, width * 0.5 + edge, e);
        s *= step(0.0001, width);
    }
    if (punch > 0.5) return src * half(1.0 - s);
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = mix(base, float3(color.rgb), s * float(color.a));
    return half4(half3(rgb) * src.a, src.a);
}
